--
-- Table structure for table `products_in_container`
--

DROP TABLE IF EXISTS `products_in_container`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products_in_container` (
  `ID` int NOT NULL AUTO_INCREMENT,
  `product_ID` int NOT NULL,
  `container_ID` int NOT NULL,
  `quantity` int NOT NULL DEFAULT '0',
  `quantity_expected` int DEFAULT NULL,
  `in_stock` tinyint(1) DEFAULT '1',
  `departure_date` date DEFAULT NULL,
  `arrival_date` date DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  KEY `product_ID` (`product_ID`),
  KEY `container_ID` (`container_ID`),
  CONSTRAINT `products_in_container_ibfk_1` FOREIGN KEY (`product_ID`) REFERENCES `products` (`ID`) ON DELETE CASCADE
