  KEY `to_stock_ID` (`to_stock_ID`),
  KEY `type_ID` (`type_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=22595 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
