DROP TABLE IF EXISTS `transferences`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transferences` (
  `ID` int NOT NULL AUTO_INCREMENT,
  `product_ID` int NOT NULL,
  `from_stock_ID` int NOT NULL,
  `to_stock_ID` int NOT NULL,
  `quantity` int NOT NULL,
  `location` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `observation` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `confirmed` tinyint(1) DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  KEY `product_ID` (`product_ID`),
  KEY `from_stock_ID` (`from_stock_ID`),
  KEY `to_stock_ID` (`to_stock_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=2419 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
